  await test('A legacy-shaped event row is backfilled to عرس with one event_honorees row', async () => {
    // The legacy shape is created here rather than sampled from the list: the
    // first row in the public list is whatever sorts earliest, which stopped
    // being a wedding the moment any other occasion type existed.
    const { insertId } = await db.execute(
      `INSERT INTO events (title, groom_name, family_clan, town, region_id, location_name, event_date, status, occasion_type_id)
       VALUES (?, ?, ?, ?, ?, ?, ?, 'approved', NULL)`,
      ['مناسبة قديمة', 'عريس ما قبل الأنواع', 'آل فلان', 'رهط', defaultRegionId, 'الديوان', '2027-04-04']
    );

    await migrate();

    const row = await db.queryOne('SELECT occasion_type_id FROM events WHERE id = ?', [insertId]);
    const wedding = await db.queryOne("SELECT id FROM occasion_types WHERE name = 'عرس'");
    assert.strictEqual(row.occasion_type_id, wedding.id);

    const honorees = await db.query('SELECT * FROM event_honorees WHERE event_id = ?', [insertId]);
    assert.strictEqual(honorees.length, 1);
    assert.strictEqual(honorees[0].name, 'عريس ما قبل الأنواع');

    await db.execute('DELETE FROM events WHERE id = ?', [insertId]);
  });

  await test('Running the migration twice does not duplicate occasion types, honorees or people', async () => {
    const beforeHonorees = await db.queryOne('SELECT COUNT(*) AS total FROM event_honorees');
    const beforeTypes = await db.queryOne('SELECT COUNT(*) AS total FROM occasion_types');
    const beforePeople = await db.queryOne('SELECT COUNT(*) AS total FROM people');
    await migrate();
    const afterHonorees = await db.queryOne('SELECT COUNT(*) AS total FROM event_honorees');
    const afterTypes = await db.queryOne('SELECT COUNT(*) AS total FROM occasion_types');
    const afterPeople = await db.queryOne('SELECT COUNT(*) AS total FROM people');
    assert.strictEqual(Number(beforeHonorees.total), Number(afterHonorees.total));
    assert.strictEqual(Number(beforeTypes.total), Number(afterTypes.total));
    // `add-people-2026-10` يملأ ما بلا شخص فقط، و`name_key` فريد — فإعادة
    // التشغيل لا تُنشئ صفّ شخص ثانياً (تذكرة #105).
    assert.strictEqual(Number(beforePeople.total), Number(afterPeople.total));
    const unlinked = await db.queryOne(
      'SELECT (SELECT COUNT(*) FROM users WHERE person_id IS NULL) + (SELECT COUNT(*) FROM photo_tags WHERE person_id IS NULL) + (SELECT COUNT(*) FROM event_honorees WHERE person_id IS NULL) AS total'
    );
    assert.strictEqual(Number(unlinked.total), 0, 'every named row is linked to a person');
  });

  await test('إعادة الترحيل لا تكرّر رسائل الأنواع المزروعة — البذرة تُكتب في نوع بلا رسالة واحدة فقط', async () => {
    // خطوة `add-occasion-type-messages-2026-11` تُشغَّل في كل `db:migrate`،
    // وشرطها أن النوع لا يحمل رسالة. تشغيلٌ ثالث بعد ولادة القاعدة يجب ألا
    // يضيف نسخة ثانية من البذرة، وألا يُلغي رسالة أطفأها أو عدّلها السوبر أدمن.
    const before = await db.queryOne('SELECT COUNT(*) AS total FROM occasion_type_messages');
    assert.ok(Number(before.total) > 0, 'set up: the migration seeded at least a few messages');

    // رسالة يكتبها الأدمن بنبرة مختلفة: البذرة لا تعرفها، وإعادة التشغيل لا تمسحها.
    const wedding = (await api('GET', '/api/occasion-types')).body.types.find(t => t.name === 'عرس');
    const custom = await api('POST', `/api/admin/occasion-types/${wedding.id}/messages`, {
      token: superAdminToken, body: { body: 'رسالة أدمن قبل إعادة الترحيل' }
    });
    assert.strictEqual(custom.status, 201, custom.body.message);

    try {
      await migrate();
      const after = await db.queryOne('SELECT COUNT(*) AS total FROM occasion_type_messages');
      assert.strictEqual(
        Number(after.total),
        Number(before.total) + 1,
        'إعادة الترحيل لم تُضف صفّاً واحداً من البذرة — الصفّ الوحيد الجديد هو رسالة الأدمن'
      );

      const kept = await db.queryOne('SELECT body FROM occasion_type_messages WHERE id = ?', [custom.body.typeMessage.id]);
      assert.ok(kept, 'ورسالة الأدمن باقية بعد الترحيل');
      assert.strictEqual(kept.body, 'رسالة أدمن قبل إعادة الترحيل');
    } finally {
      await db.execute('DELETE FROM occasion_type_messages WHERE id = ?', [custom.body.typeMessage.id]);
    }
  });

