  // الاسم هنا يختلف عن الاسم المخزَّن بحرف «ال» وحده: الحارس يوحّد الإملاء
  // فيراهما اسماً واحداً ('certain')، بينما فحص السكربت القديم
  // (`groom_name = ? AND event_date = ?`) لا يراهما متطابقين — فالقرار الذي
  // نقرأه في المخرَج هو قرار الحارس حتماً، لا قرار «موجودة مسبقاً».
  // ======================================================================
  console.log('\nسكربتات الاستيراد لا تتخطّى حارس التكرار (تذكرة #160)');

  const importGuard = require('../scripts/import-duplicate-guard');
  const importGuardStamp = Date.now();
  // 'محمد حارس<stamp>' (المستورَد) و'محمد الحارس<stamp>' (القائم): مفتاح
  // `nameTokens` واحد بعد إسقاط «ال»، والنصّان مختلفان حرفياً.
  const importGuardStoredName = `محمد الحارس${importGuardStamp}`;
  const importGuardInputName = `محمد حارس${importGuardStamp}`;
  const importGuardFamily = `عائلة الحارس ${importGuardStamp}`;
  const importGuardSkipPoster = `https://munasabatna.com/test-guard-${importGuardStamp}.jpg`;
  const importGuardFreshPoster = `https://munasabatna.com/test-fresh-${importGuardStamp}.jpg`;
  const importGuardEventIds = [];

  const { insertId: importGuardExistingId } = await db.execute(
    `INSERT INTO events (title, groom_name, family_clan, town, region_id, location_name, event_date, status)
     VALUES (?, ?, ?, 'حورة', ?, 'ديوان التكرار', '2029-02-10', 'approved')`,
    [`أفراح المستورد ${importGuardStamp}`, importGuardStoredName, importGuardFamily, defaultRegionId]
  );
  importGuardEventIds.push(importGuardExistingId);

  /** يشغّل سكربت الإدراج الحقيقي على مدخلات مُصنَّعة، ويعيد مخرَجه النصّي. */
  function runMunasabatnaInsert(entries) {
    const { execFileSync } = require('child_process');
    return execFileSync(
      process.execPath,
      [path.join(__dirname, '..', 'scripts', 'munasabatna-insert.js')],
      { input: JSON.stringify(entries), encoding: 'utf8' }
    );
  }

  try {
    await test('نقطة فحص الاستيراد تقرأ قرار حارس التكرار من الخدمة نفسها (تذكرة #160)', async () => {
      const subject = {
        names: [importGuardInputName],
        family_clan: importGuardFamily,
        region_id: defaultRegionId,
        town: 'حورة',
        event_date: '2029-02-10',
        event_end_date: null
      };

      // الخدمة ترى المرشّح بنفسها — وهي ما تناديه `checkImportEntry` حرفياً.
      const [candidates] = await eventsService.findPossibleDuplicates([subject]);
      const candidate = candidates.find(row => row.id === importGuardExistingId);
      assert.ok(candidate, JSON.stringify(candidates));
      assert.strictEqual(candidate.confidence, 'certain');

      const decision = await importGuard.checkImportEntry(subject);
      assert.strictEqual(decision.action, 'skip', 'الشبه يعطي قرار تخطٍّ لا إدراجاً');
      assert.strictEqual(decision.match.id, importGuardExistingId);
      assert.strictEqual(decision.match.confidence, 'certain');
      assert.deepStrictEqual(decision.match.reasons, ['الاسم مطابق', 'نفس التاريخ', 'نفس البلدة']);

      const clear = await importGuard.checkImportEntry({
        names: [`سالم${importGuardStamp} النجار`],
        family_clan: '',
        region_id: defaultRegionId,
        town: 'رهط',
        event_date: '2029-03-15',
        event_end_date: null
      });
      assert.strictEqual(clear.action, 'insert', 'ما لا يشبه مناسبة قائمة يبقى قراره الإدراج');
    });

    await test('munasabatna-insert لا يدرج المشتبه، ويطبعه في قسم «تُخطِّي» مع المطابقة ودرجتها (تذكرة #160)', async () => {
      const output = runMunasabatnaInsert([{
        groom_name: importGuardInputName,
        family_clan: importGuardFamily,
        town: 'حورة',
        location_name: 'ديوان التكرار',
        event_date: '2029-02-10',
        poster_url: importGuardSkipPoster
      }]);

      const written = await db.queryOne('SELECT id FROM events WHERE poster_url = ?', [importGuardSkipPoster]);
      assert.strictEqual(written, null, 'المشتبه لا يُكتب في القاعدة إطلاقاً');
      assert.ok(/— أُدرج \(0\) —/.test(output), output);
      assert.ok(/— تُخطِّي \(1\) —/.test(output), output);
      assert.ok(output.includes(`#${importGuardExistingId}`), `المناسبة القائمة بمعرّفها: ${output}`);
      assert.ok(output.includes(importGuardStoredName), `وعنوانها/أصحابها: ${output}`);
      assert.ok(/درجة الشبه: certain/.test(output), `درجة الشبه: ${output}`);
      assert.ok(output.includes('الاسم مطابق'), `أسباب الشبه: ${output}`);
      assert.ok(/الخلاصة: أُدرج 0 · تُخطِّي 1/.test(output), output);
    });

    await test('munasabatna-insert يُدرج المدخل غير المشتبه كما كان، ويعدّه في قسم «أُدرج» (تذكرة #160)', async () => {
      const output = runMunasabatnaInsert([{
        groom_name: `سالم${importGuardStamp} النجار`,
        town: 'رهط',
        location_name: 'قاعة الاختبار',
        event_date: '2029-03-15',
        poster_url: importGuardFreshPoster
      }]);

      const written = await db.queryOne(
        'SELECT id, town, status FROM events WHERE poster_url = ?', [importGuardFreshPoster]
      );
      assert.ok(written, `غير المشتبه يُدرج كما اليوم: ${output}`);
      importGuardEventIds.push(written.id);
      assert.strictEqual(written.town, 'رهط');
      assert.strictEqual(written.status, 'approved');
      assert.ok(/— أُدرج \(1\) —/.test(output), output);
      assert.ok(/— تُخطِّي \(0\) —/.test(output), output);
      assert.ok(/الخلاصة: أُدرج 1 · تُخطِّي 0/.test(output), output);

      // تشغيل ثانٍ للمدخل نفسه: «موجودة مسبقاً» قسم مستقل، لا يُخلط بعدّاد
      // «تُخطِّي» الذي يعدّ ما أوقفه الحارس وحده — ودونه يُقرأ العدد على أنه
      // «بطاقة أوقفها الحارس» وهو ليس كذلك.
      const repeatOutput = runMunasabatnaInsert([{
        groom_name: `سالم${importGuardStamp} النجار`,
        town: 'رهط',
        location_name: 'قاعة الاختبار',
        event_date: '2029-03-15',
        poster_url: importGuardFreshPoster
      }]);
      assert.ok(/— أُدرج \(0\) —/.test(repeatOutput), repeatOutput);
      assert.ok(/— تُخطِّي \(0\) —/.test(repeatOutput), repeatOutput);
      assert.ok(/— موجودة مسبقاً \(1\) —/.test(repeatOutput), repeatOutput);
      assert.ok(/الخلاصة: أُدرج 0 · تُخطِّي 0 · موجودة مسبقاً 1/.test(repeatOutput), repeatOutput);
      const stillOne = await db.queryOne(
        'SELECT COUNT(*) AS total FROM events WHERE poster_url = ?', [importGuardFreshPoster]
      );
      assert.strictEqual(Number(stillOne.total), 1, 'التشغيل الثاني لا يكتب صفّاً ثانياً');
    });

    await test('import-legacy-json يمرّر العائلة الحقيقية ويمرّ على الحارس، وتقريره يفصل الأقسام الأربعة (تذكرة #160)', async () => {
      const legacyStamp = `${importGuardStamp}-legacy`;
      const legacyExistingTitle = `قائمة قديمة ${legacyStamp}`;
      const legacyExistingGroom = `سالم ${importGuardStamp} النجار`;
      // مناسبة قائمة تحمل اسم البلدة في family_clan — كما يكتبها المستورد القديم
      // لصفّ لا عائلة له (`event.family_clan || event.town`).
      const { insertId: legacyExistingId } = await db.execute(
        `INSERT INTO events (title, groom_name, family_clan, town, region_id, location_name, event_date, status)
         VALUES (?, ?, 'حورة', 'حورة', ?, 'ديوان', '2029-05-01', 'approved')`,
        [legacyExistingTitle, legacyExistingGroom, defaultRegionId]
      );
      importGuardEventIds.push(legacyExistingId);

      const legacyTitle = `مناسبة قديمة مختلفة ${legacyStamp}`;
      // 'النجار' و'نجار' مفتاح واحد عند الحارس («ال» تُسقَط) ونصّان مختلفان في
      // فحص «موجودة مسبقاً» الحرفي — فالسقوط هنا سقوط استدعاء الحارس نفسه.
      const legacySuspectedGroom = `سالم ${importGuardStamp} نجار`;
      const dir = await fsp.mkdtemp(path.join(require('os').tmpdir(), 'negev-legacy-'));
      const file = path.join(dir, 'legacy.json');
      await fsp.writeFile(file, JSON.stringify({
        users: [],
        events: [
          {
            id: 9001,
            title: legacyTitle,
            groom_name: `خالد${importGuardStamp}`,
            town: 'حورة',
            location_name: 'ديوان ثانٍ',
            event_date: '2029-05-02'
          },
          {
            id: 9002,
            title: `بطاقة مشابهة ${legacyStamp}`,
            groom_name: legacySuspectedGroom,
            town: 'حورة',
            location_name: 'ديوان ثالث',
            event_date: '2029-05-01'
          },
          {
            id: 9003,
            title: `مدخل ناقص ${legacyStamp}`,
            groom_name: 'ناقص'
          }
        ],
        reactions: [],
        congratulations: [],
        nokoot_ledger: [],
        stories: []
      }), 'utf8');

      const { execFileSync } = require('child_process');
      const legacyOutput = execFileSync(
        process.execPath,
        [path.join(__dirname, '..', 'scripts', 'import-legacy-json.js'), file],
        { encoding: 'utf8' }
      );

      const written = await db.queryOne('SELECT id, family_clan FROM events WHERE title = ?', [legacyTitle]);
      assert.ok(written, `اسم البلدة ليس عائلة: المناسبة المختلفة تُدرَج — ${legacyOutput}`);
      importGuardEventIds.push(written.id);
      // الصفّ يُكتب كما كان (اسم البلدة في family_clan حين تغيب العائلة)؛
      // التغيير في ما يراه الحارس وحده.
      assert.strictEqual(written.family_clan, 'حورة');

      // استدعاء الحارس في هذا السكربت نفسه: البطاقة الشبيهة لا تُكتب إطلاقاً.
      const suspected = await db.queryOne('SELECT id FROM events WHERE groom_name = ?', [legacySuspectedGroom]);
      assert.strictEqual(suspected, null, `المشتبه لا يُدرج — ${legacyOutput}`);
      assert.ok(legacyOutput.includes(legacyExistingTitle), `المناسبة المطابقة في التقرير: ${legacyOutput}`);
      assert.ok(/درجة الشبه: certain/.test(legacyOutput), legacyOutput);

      // الأقسام الأربعة، ومجموعها عدد مدخلات الملف (٣)، بلا دمج «موجودة مسبقاً»
      // في «تُخطِّي» — والمدخل الناقص له قسمه بدل أن يُسقَط من الحساب.
      assert.ok(legacyOutput.includes('— أُدرج (1) —'), legacyOutput);
      assert.ok(legacyOutput.includes('— تُخطِّي (1) —'), legacyOutput);
      assert.ok(legacyOutput.includes('— موجودة مسبقاً (0) —'), legacyOutput);
      assert.ok(legacyOutput.includes('— مشوّه/متجاهَل (1) —'), legacyOutput);
      assert.ok(
        legacyOutput.includes('الخلاصة: أُدرج 1 · تُخطِّي 1 · موجودة مسبقاً 0 · مشوّه 1 · المجموع 3'),
        legacyOutput
      );
      assert.ok(legacyOutput.includes('1 malformed (3 in file)'), legacyOutput);
      await fsp.rm(dir, { recursive: true, force: true });
    });
  } finally {
    if (importGuardEventIds.length) {
      await db.execute(
        `DELETE FROM events WHERE id IN (${importGuardEventIds.map(() => '?').join(', ')})`,
        importGuardEventIds
      );
    }
  }

  // ======================================================================
  // اللوحة: جغرافيا المنطقتين والبثّ والتحليلات (تذكرة #128)
  //
  // كل صفوف هذا القسم تُنشأ هنا وتُحذف في آخره: محافظة، بلدتان فيها، قرية
  // بمحافظتها، وأدمن بلدتين، وتعيمانان، وصفّ تحليلات بمحتوى إحدى بلدتيها.
  // الأسماء مؤقّتة وفريدة كي لا تصادم تشغيلاً سابقاً فاشلاً.
  // ======================================================================
  console.log('\nاللوحة: جغرافيا المنطقتين والبثّ والتحليلات (تذكرة #128)');

  const ticket128RegionName = `محافظة لوحة ${Date.now()}`;
  const ticket128TownA = `بلدة لوحة أ ${Date.now()}`;
  const ticket128TownB = `بلدة لوحة ب ${Date.now()}`;
  const ticket128VillageName = `قرية لوحة ${Date.now()}`;
  const ticket128Cleanup = {
    regionIds: [], townIds: [], villageIds: [], userIds: [], broadcastIds: [], eventIds: [],
    contentTowns: [ticket128TownA, ticket128TownB]
  };
  // معرّف جهاز فريد لكل صفّ تحليلات يكتبه هذا القسم: ينظّفه وحده (LIKE 'ticket128-%')
  // ويجعل «المشاهدين الفريدين» قابلة للحساب بالضبط، لا `>= 1`.
  let ticket128DeviceSeq = 0;
  const ticket128Device = () => `ticket128-${Date.now()}-${++ticket128DeviceSeq}`;

  let ticket128RegionId = 0;
  await test('POST /api/admin/regions ينشئ محافظة على نمط «إضافة بلدة»؛ الاسم المكرر 409، وبلا إحداثيات 400، وأدمن بلدة 403 (تذكرة #128)', async () => {
    const created = await api('POST', '/api/admin/regions', {
      token: superAdminToken,
      body: { name: ticket128RegionName, latitude: 32.31, longitude: 35.03 }
    });
    assert.strictEqual(created.status, 201, JSON.stringify(created.body));
    assert.strictEqual(created.body.success, true);
    ticket128RegionId = created.body.region.id;
    ticket128Cleanup.regionIds.push(ticket128RegionId);

    const region = created.body.region;
    assert.strictEqual(region.name, ticket128RegionName);
    assert.strictEqual(Number(region.latitude), 32.31);
    assert.strictEqual(Number(region.longitude), 35.03);
    assert.strictEqual(Number(region.map_zoom), 9, 'بلا map_zoom يأخذ افتراضي العمود نفسه');
    assert.strictEqual(region.is_active, true);
    assert.deepStrictEqual(region.towns, [], 'محافظة جديدة تبدأ بلا بلدات');

    // الترتيب في النهاية ما لم يُرسَل صراحةً — نفس قاعدة createTown.
    const { maxPosition } = await db.queryOne('SELECT COALESCE(MAX(position), -1) AS maxPosition FROM regions WHERE id <> ?', [ticket128RegionId]);
    assert.strictEqual(Number(region.position), Number(maxPosition) + 1);

    const duplicate = await api('POST', '/api/admin/regions', {
      token: superAdminToken,
      body: { name: `  ${ticket128RegionName}  `, latitude: 32.3, longitude: 35 }
    });
    assert.strictEqual(duplicate.status, 409, 'اسم مكرّر (بعد trim) يُرفض');
    assert.ok(/مسبقاً|اسم محافظة/.test(duplicate.body.message || ''), duplicate.body.message);

    const noCoords = await api('POST', '/api/admin/regions', {
      token: superAdminToken,
      body: { name: `${ticket128RegionName} بلا إحداثيات` }
    });
    assert.strictEqual(noCoords.status, 400);
    assert.ok(/خط العرض مطلوب/.test(noCoords.body.message || ''), noCoords.body.message);

    const badZoom = await api('POST', '/api/admin/regions', {
      token: superAdminToken,
      body: { name: `${ticket128RegionName} بتقريب خاطئ`, latitude: 32.3, longitude: 35, map_zoom: 30 }
    });
    assert.strictEqual(badZoom.status, 400);
    assert.ok(/التقريب|تقريب/.test(badZoom.body.message || ''), badZoom.body.message);

    const townAdminAttempt = await api('POST', '/api/admin/regions', {
      token: scopedAdminToken,
      body: { name: `${ticket128RegionName} من أدمن`, latitude: 32.3, longitude: 35 }
    });
    assert.strictEqual(townAdminAttempt.status, 403, 'أدمن بلدة لا ينشئ محافظة');

    const userAttempt = await api('POST', '/api/admin/regions', {
      token: userToken,
      body: { name: `${ticket128RegionName} من مستخدم`, latitude: 32.3, longitude: 35 }
    });
    assert.strictEqual(userAttempt.status, 403, 'ولا مستخدم عادي');

    const { total } = await db.queryOne('SELECT COUNT(*) AS total FROM regions WHERE name LIKE ?', [`%${ticket128RegionName}%`]);
    assert.strictEqual(Number(total), 1, 'كل الطلبات المرفوضة كتبت صفر صفوف');
  });

  let ticket128VillageId = 0;
  await test('POST /api/admin/villages بمحافظة يُخزّنها، و GET /api/admin/villages يعيد region_id في الصفّ (تذكرة #128)', async () => {
    const created = await api('POST', '/api/admin/villages', {
      token: superAdminToken,
      body: {
        region_id: ticket128RegionId,
        name: ticket128VillageName,
        latitude: 32.32,
        longitude: 35.04
      }
    });
    assert.strictEqual(created.status, 201, JSON.stringify(created.body));
    ticket128VillageId = created.body.village.id;
    ticket128Cleanup.villageIds.push(ticket128VillageId);
    assert.strictEqual(created.body.village.region_id, ticket128RegionId);

    const row = await db.queryOne('SELECT region_id FROM villages WHERE id = ?', [ticket128VillageId]);
    assert.strictEqual(row.region_id, ticket128RegionId, 'المحافظة المرسلة هي المخزَّنة، لا الافتراضية');

    // اللوحة تفلتر القرى عميلياً على region_id هذا في كل صفّ.
    const list = await api('GET', '/api/admin/villages', { token: superAdminToken });
    const listed = list.body.villages.find(village => village.id === ticket128VillageId);
    assert.ok(listed, 'القرية الجديدة ظاهرة في قائمة اللوحة');
    assert.strictEqual(listed.region_id, ticket128RegionId);
  });

  let ticket128AdminToken = '';
  await test('بثّ باسم محافظة يكتب صفّاً لكل بلدة من بلداتها داخل نطاق الأدمن، ولا صفّ باسم المحافظة نفسه (تذكرة #128)', async () => {
    for (const [name, latitude] of [[ticket128TownA, 32.33], [ticket128TownB, 32.34]]) {
      const town = await api('POST', '/api/admin/towns', {
        token: superAdminToken,
        body: { region_id: ticket128RegionId, name, latitude, longitude: 35.05 }
      });
      assert.strictEqual(town.status, 201, town.body.message);
      ticket128Cleanup.townIds.push(town.body.town.id);
    }

    const adminPhone = `05${Math.floor(10000000 + Math.random() * 89999999)}`;
    const { insertId: adminId } = await db.execute(
      `INSERT INTO users (phone_number, full_name, pin_code, clan_town, role) VALUES (?, ?, ?, ?, 'admin')`,
      [adminPhone, 'أدمن محافظة الاختبار', bcrypt.hashSync('1234', config.bcryptRounds), ticket128TownA]
    );
    ticket128Cleanup.userIds.push(adminId);
    ticket128AdminToken = signToken(
      { id: adminId, phone_number: adminPhone, full_name: 'أدمن محافظة الاختبار', role: 'admin' },
      '1h'
    );

    const assigned = await api('PUT', `/api/admin/admins/${adminId}/towns`, {
      token: superAdminToken,
      body: { towns: [ticket128TownA, ticket128TownB] }
    });
    assert.strictEqual(assigned.status, 200, JSON.stringify(assigned.body));

    // اسم المحافظة وحده في الطلب — التوسيع كله داخل adminScope.service.js.
    const broadcast = await api('POST', '/api/admin/broadcast', {
      token: ticket128AdminToken,
      body: { message: 'تعميم محافظة الاختبار', duration: 'none', towns: [ticket128RegionName] }
    });
    assert.strictEqual(broadcast.status, 200, JSON.stringify(broadcast.body));
    assert.strictEqual(broadcast.body.broadcasts.length, 2, 'صفّ لكل بلدة من بلدات المحافظة في نطاق الأدمن');
    broadcast.body.broadcasts.forEach(row => ticket128Cleanup.broadcastIds.push(row.id));
    assert.deepStrictEqual(
      broadcast.body.broadcasts.map(row => row.scope_town).sort(),
      [ticket128TownA, ticket128TownB].sort()
    );

    const rows = await db.query(
      `SELECT scope_town FROM broadcasts WHERE id IN (${broadcast.body.broadcasts.map(() => '?').join(', ')})`,
      broadcast.body.broadcasts.map(row => row.id)
    );
    const scopes = rows.map(row => row.scope_town).sort();
    assert.deepStrictEqual(scopes, [ticket128TownA, ticket128TownB].sort(), 'broadcasts.scope_town في القاعدة نفسها');
    assert.ok(!scopes.includes(ticket128RegionName), 'لا صفّ باسم المحافظة — التوسيع إلى بلداتها');
  });

  await test('أدمن يملك بلدة واحدة في المحافظة يبثّ لها وحدها؛ وأدمن لا يملك شيئاً منها يُرفض 404 بلا كتابة (تذكرة #128)', async () => {
    const singlePhone = `05${Math.floor(10000000 + Math.random() * 89999999)}`;
    const { insertId: singleAdminId } = await db.execute(
      `INSERT INTO users (phone_number, full_name, pin_code, clan_town, role) VALUES (?, ?, ?, ?, 'admin')`,
      [singlePhone, 'أدمن بلدة واحدة في المحافظة', bcrypt.hashSync('1234', config.bcryptRounds), ticket128TownA]
    );
    ticket128Cleanup.userIds.push(singleAdminId);
    const singleAdminToken = signToken(
      { id: singleAdminId, phone_number: singlePhone, full_name: 'أدمن بلدة واحدة في المحافظة', role: 'admin' },
      '1h'
    );
    await api('PUT', `/api/admin/admins/${singleAdminId}/towns`, {
      token: superAdminToken,
      body: { towns: [ticket128TownA] }
    });

    const one = await api('POST', '/api/admin/broadcast', {
      token: singleAdminToken,
      body: { message: 'تعميم بلدة واحدة من المحافظة', duration: 'none', towns: [ticket128RegionName] }
    });
    assert.strictEqual(one.status, 200, JSON.stringify(one.body));
    assert.strictEqual(one.body.broadcasts.length, 1, 'صفّ واحد فقط، لا المحافظة كلها');
    assert.strictEqual(one.body.broadcasts[0].scope_town, ticket128TownA);
    ticket128Cleanup.broadcastIds.push(one.body.broadcasts[0].id);

    // أدمن يملك بلدة في محافظة أخرى تماماً — لا يملك أي بلدة في هذه المحافظة →
    // نفس 404 البلدة الغريبة، لا 403. حسابه خاص بهذا القسم: `scopedAdminId`
    // السابق حُذف في قسم سابق، وحساب محذوف لا يملك بلدات.
    const foreignPhone = `05${Math.floor(10000000 + Math.random() * 89999999)}`;
    const { insertId: foreignAdminId } = await db.execute(
      `INSERT INTO users (phone_number, full_name, pin_code, clan_town, role) VALUES (?, ?, ?, ?, 'admin')`,
      [foreignPhone, 'أدمن محافظة أخرى', bcrypt.hashSync('1234', config.bcryptRounds), scopedTown]
    );
    ticket128Cleanup.userIds.push(foreignAdminId);
    const foreignAdminToken = signToken(
      { id: foreignAdminId, phone_number: foreignPhone, full_name: 'أدمن محافظة أخرى', role: 'admin' },
      '1h'
    );
    await api('PUT', `/api/admin/admins/${foreignAdminId}/towns`, {
      token: superAdminToken,
      body: { towns: [scopedTown] }
    });

    const before = await db.queryOne('SELECT COUNT(*) AS total FROM broadcasts');
    const foreign = await api('POST', '/api/admin/broadcast', {
      token: foreignAdminToken,
      body: { message: 'تعميم محافظة خارج النطاق', duration: 'none', towns: [ticket128RegionName] }
    });
    assert.strictEqual(foreign.status, 404);
    assert.ok(/بلدة غير موجودة ضمن نطاقك/.test(foreign.body.message || ''), foreign.body.message);
    const after = await db.queryOne('SELECT COUNT(*) AS total FROM broadcasts');
    assert.strictEqual(Number(after.total), Number(before.total), 'الرفض لا يكتب أي صفّ');
  });

  await test('سوبر أدمن يسمّي محافظة: صفّ لكل بلدة نشطة فيها ولا صفّ عام؛ وبلا اسم: صفّ عام واحد كما كان (تذكرة #128)', async () => {
    const byRegion = await api('POST', '/api/admin/broadcast', {
      token: superAdminToken,
      body: { message: 'تعميم السوبر أدمن لمحافظة الاختبار', duration: 'none', towns: [ticket128RegionName] }
    });
    assert.strictEqual(byRegion.status, 200, JSON.stringify(byRegion.body));
    byRegion.body.broadcasts.forEach(row => ticket128Cleanup.broadcastIds.push(row.id));
    assert.strictEqual(byRegion.body.broadcasts.length, 2, 'صفّ لكل بلدة نشطة في المحافظة، لا أكثر');
    assert.deepStrictEqual(
      byRegion.body.broadcasts.map(row => row.scope_town).sort(),
      [ticket128TownA, ticket128TownB].sort(),
      'لا صفّ عام NULL ولا صفّ باسم المحافظة — بلداتها النشطة وحدها'
    );

    const scopedRows = await db.query(
      `SELECT scope_town FROM broadcasts WHERE id IN (${byRegion.body.broadcasts.map(() => '?').join(', ')})`,
      byRegion.body.broadcasts.map(row => row.id)
    );
    assert.deepStrictEqual(scopedRows.map(row => row.scope_town).sort(), [ticket128TownA, ticket128TownB].sort());
    assert.ok(scopedRows.every(row => row.scope_town !== null), 'ولا صفّ عام بينها');

    // وبلا `towns` يبقى البثّ العام: صفّ واحد `scope_town = NULL` لكل المنصة.
    const globalBefore = await db.queryOne('SELECT COUNT(*) AS total FROM broadcasts WHERE scope_town IS NULL');
    const global = await api('POST', '/api/admin/broadcast', {
      token: superAdminToken,
      body: { message: 'تعميم السوبر أدمن العام', duration: 'none' }
    });
    assert.strictEqual(global.status, 200, JSON.stringify(global.body));
    assert.strictEqual(global.body.broadcasts.length, 1, 'صفّ عام واحد، لا صفّ لكل بلدة');
    assert.strictEqual(global.body.broadcasts[0].scope_town, null);
    ticket128Cleanup.broadcastIds.push(global.body.broadcasts[0].id);
    const globalAfter = await db.queryOne('SELECT COUNT(*) AS total FROM broadcasts WHERE scope_town IS NULL');
    assert.strictEqual(Number(globalAfter.total), Number(globalBefore.total) + 1);
  });

  /** لقطة من `GET /api/admin/analytics/overview` — الفرق بين لقطتين يُقاس بالضبط. */
  const ticket128Overview = async () => {
    const { status, body } = await api('GET', '/api/admin/analytics/overview?period=all', { token: superAdminToken });
    assert.strictEqual(status, 200, JSON.stringify(body));
    return body.overview;
  };

  await test('GET /api/admin/analytics/overview يحمل by_region إضافياً، وحدثان على بلدة المحافظة الثانية يزيدانها اثنين بالضبط (تذكرة #128)', async () => {
    const before = await ticket128Overview();

    // الشكل القائم كما هو بالحرف — الإضافة مفتاح جديد وحده.
    assert.deepStrictEqual(Object.keys(before).sort(), ['audience', 'by_region', 'clicks', 'period', 'platforms', 'shares', 'views']);
    assert.deepStrictEqual(Object.keys(before.views).sort(), ['breakdown', 'total', 'unique']);
    assert.deepStrictEqual(Object.keys(before.shares).sort(), ['total', 'unique']);
    assert.deepStrictEqual(Object.keys(before.clicks).sort(), ['breakdown', 'total', 'unique']);
    assert.deepStrictEqual(Object.keys(before.platforms).sort(), ['mobile', 'web']);
    assert.deepStrictEqual(Object.keys(before.audience).sort(), ['registered_users', 'total_active_devices', 'unregistered_devices']);
    assert.strictEqual(before.period, 'all');

    // صفّ لكل محافظة، + صفّ واحد «غير محدَّد» لما تعذّر إسناده — لا صفّ يُسقَط.
    const { total: regionsCount } = await db.queryOne('SELECT COUNT(*) AS total FROM regions');
    assert.strictEqual(before.by_region.length, Number(regionsCount) + 1, 'كل محافظة + صفّ «غير محدَّد»');
    const unassignedRows = before.by_region.filter(row => row.region_id === null);
    assert.strictEqual(unassignedRows.length, 1, 'صفّ «غير محدَّد» واحد لا أكثر');
    assert.strictEqual(unassignedRows[0].name, 'غير محدَّد');

    // المجاميع تساوي الملخّص بالحرف — هذا ما يجعله تجميعاً لا تقريراً ثانياً.
    const sumOf = (rows, pick) => rows.reduce((total, row) => total + pick(row), 0);
    assert.strictEqual(sumOf(before.by_region, row => row.views.total), before.views.total);
    assert.strictEqual(sumOf(before.by_region, row => row.shares.total), before.shares.total);
    assert.strictEqual(sumOf(before.by_region, row => row.clicks.total), before.clicks.total);

    const regionBefore = before.by_region.find(row => row.region_id === ticket128RegionId);
    assert.ok(regionBefore, 'المحافظة الجديدة ظاهرة في التجميع');
    assert.strictEqual(regionBefore.name, ticket128RegionName);
    assert.deepStrictEqual(Object.keys(regionBefore).sort(), ['audience', 'clicks', 'name', 'region_id', 'shares', 'views']);
    assert.deepStrictEqual(Object.keys(regionBefore.views).sort(), ['total', 'unique']);

    // حدثان (مشاهدتان) على بلدة في هذه المحافظة، عبر الخدمة لا مسار
    // POST /api/analytics/events: ذاك على دلو الطلبات المجهولة، والقسم هنا يقيس
    // التجميع لا تحديد المعدّل.
    await analyticsService.record({ eventName: 'event_viewed', deviceId: ticket128Device(), platform: 'web', contentTown: ticket128TownA });
    await analyticsService.record({ eventName: 'event_viewed', deviceId: ticket128Device(), platform: 'web', contentTown: ticket128TownA });

    const after = await ticket128Overview();
    const regionAfter = after.by_region.find(row => row.region_id === ticket128RegionId);
    assert.strictEqual(regionAfter.views.total, regionBefore.views.total + 2, 'الزيادة = عدد الحدثين بالضبط');
    assert.strictEqual(regionAfter.views.unique, regionBefore.views.unique + 2, 'جهازان مختلفان = مشاهدَين فريدين');
    assert.strictEqual(after.views.total, before.views.total + 2, 'الملخّص نفسه يزيد اثنين أيضاً');
    assert.strictEqual(sumOf(after.by_region, row => row.views.total), after.views.total, 'والمجاميع تبقى مطابقة');

    // ولا صفّ آخر تحرّك: حدثا بلدة المحافظة الثانية لم يُضافا إلى محافظة أخرى.
    for (const row of after.by_region) {
      if (row.region_id === ticket128RegionId) continue;
      const previous = before.by_region.find(candidate => candidate.region_id === row.region_id);
      assert.deepStrictEqual(row, previous, `لا صفّ آخر تغيّر — ${row.name}`);
    }
  });

  await test('صفّ بـ content_town = «القرى والتجمعات» مع مناسبة في المحافظة الثانية يذهب إلى «غير محدَّد» ولا يُسقَط (تذكرة #128)', async () => {
    // مناسبة حقيقية في المحافظة الثانية تحت البند الجامع، كي لا يكون الاختبار
    // نظرياً: الصفّ التحليلي يحمل اسم البند الجامع وحده، بلا معرّف مناسبة.
    const catchAllEvent = await api('POST', '/api/events', {
      token: superAdminToken,
      body: weddingEventBody({
        honorees: [{ name: `عريس البند الجامع ${Date.now()}` }],
        town: 'القرى والتجمعات',
        requested_village_name: `قرية غير معلنة ${Date.now()}`,
        region_id: ticket128RegionId,
        event_date: '2027-04-01'
      })
    });
    assert.strictEqual(catchAllEvent.status, 201, catchAllEvent.body.message);
    ticket128Cleanup.eventIds.push(catchAllEvent.body.eventId);

    const before = await ticket128Overview();
    const unassignedBefore = before.by_region.find(row => row.region_id === null);
    const regionBefore = before.by_region.find(row => row.region_id === ticket128RegionId);
    assert.ok(unassignedBefore && regionBefore);

    await analyticsService.record({
      eventName: 'share_clicked',
      deviceId: ticket128Device(),
      platform: 'web',
      contentTown: 'القرى والتجمعات'
    });

    const after = await ticket128Overview();
    const unassignedAfter = after.by_region.find(row => row.region_id === null);
    const regionAfter = after.by_region.find(row => row.region_id === ticket128RegionId);

    // الإسناد الدقيق مستحيل: analytics_events لا يحمل content_id/event_id، فاسم
    // البند الجامع لا يقود إلى محافظة المناسبة. لا نُسقطه ولا نخترع له محافظة.
    assert.strictEqual(unassignedAfter.shares.total, unassignedBefore.shares.total + 1, 'المشاركة تذهب إلى «غير محدَّد»');
    assert.strictEqual(unassignedAfter.shares.unique, unassignedBefore.shares.unique + 1);
    assert.strictEqual(after.shares.total, before.shares.total + 1, 'وتبقى داخل المجموع كاملاً');
    assert.strictEqual(regionAfter.shares.total, regionBefore.shares.total, 'ولا تُنسب إلى محافظة المناسبة اختراعاً');
    assert.strictEqual(after.by_region.length, before.by_region.length, 'ولا يُضاف صفّ آخر');
  });

  // تنظيف القسم: البثّ، ثم التحليلات (بلدتاه + كل جهاز باسم ticket128-)، ثم
  // المناسبات وسجلّها، ثم القرية، ثم إسنادات الأدمن وحساباتهم، ثم البلدات،
  // ثم المحافظة. صفوف التحليلات تُحدَّد بمعرّف الجهاز أيضاً كي لا يُمسّ صفّ
  // قديم بالبند الجامع سبق هذا القسم.
  if (ticket128Cleanup.broadcastIds.length) {
    await db.execute(
      `DELETE FROM broadcasts WHERE id IN (${ticket128Cleanup.broadcastIds.map(() => '?').join(', ')})`,
      ticket128Cleanup.broadcastIds
    );
  }
  await db.execute(
    `DELETE FROM analytics_events
      WHERE content_town IN (${ticket128Cleanup.contentTowns.map(() => '?').join(', ')})
         OR device_id LIKE 'ticket128-%'`,
    ticket128Cleanup.contentTowns
  );
  if (ticket128Cleanup.eventIds.length) {
    await db.execute(
      `DELETE FROM activity_log WHERE event_id IN (${ticket128Cleanup.eventIds.map(() => '?').join(', ')})`,
      ticket128Cleanup.eventIds
    );
    await db.execute(
      `DELETE FROM events WHERE id IN (${ticket128Cleanup.eventIds.map(() => '?').join(', ')})`,
      ticket128Cleanup.eventIds
    );
  }
  if (ticket128Cleanup.villageIds.length) {
    await db.execute(
      `DELETE FROM villages WHERE id IN (${ticket128Cleanup.villageIds.map(() => '?').join(', ')})`,
      ticket128Cleanup.villageIds
    );
  }
  if (ticket128Cleanup.userIds.length) {
    await db.execute(
      `DELETE FROM admin_towns WHERE user_id IN (${ticket128Cleanup.userIds.map(() => '?').join(', ')})`,
      ticket128Cleanup.userIds
    );
    await db.execute(
      `DELETE FROM users WHERE id IN (${ticket128Cleanup.userIds.map(() => '?').join(', ')})`,
      ticket128Cleanup.userIds
    );
  }
  if (ticket128Cleanup.townIds.length) {
    await db.execute(
      `DELETE FROM towns WHERE id IN (${ticket128Cleanup.townIds.map(() => '?').join(', ')})`,
      ticket128Cleanup.townIds
    );
  }
  if (ticket128Cleanup.regionIds.length) {
    await db.execute(
      `DELETE FROM regions WHERE id IN (${ticket128Cleanup.regionIds.map(() => '?').join(', ')})`,
      ticket128Cleanup.regionIds
    );
  }

  // ────────────────────────────────────────────────────────────────────────────
  // «آخر خبر» — القارئ الإخباري في وجهة «خدماتنا»، ومصدره منصة كترا الخارجية.
  //
  // المصدر خادم HTTP وهمي على منفذ عابر: العقد يُختبَر كما يُنشَر (شبكة حقيقية
  // في العملية نفسها)، ولا يتوقّف الاختبار على توفّر خادم طرف ثالث في وقت
  // التشغيل. `KATRA_NEWS_CACHE_TTL_MS=0` يجعل كل طلب يذهب إلى المصدر — وهو ما
  // يسمح بإثبات «النسخة القديمة تُخدَم عند السقوط» بدل إثبات مهلة كاش غير مرئية.
  // ────────────────────────────────────────────────────────────────────────────
  console.log('\nآخر خبر: أخبار المحافظة وتفصيلها من منصة كترا (وجهة «خدماتنا»)');

  const newsRegionRow = await db.queryOne('SELECT id, name FROM regions WHERE name = ?', [SEED_REGION.name]);
  assert.ok(newsRegionRow, 'the seeded governorate must exist — it is the key of the news area map');

  // عنصران منهما يُسقطهما التطبيع: بلا معرّف وبلا عنوان. ثم اثنان وخمسون سليماً.
  const KATRA_FIXTURE_ITEMS = Array.from({ length: 52 }, (_, index) => ({
    id: 900 + index,
    title: `خبر الاختبار ${index + 1}`,
    // ثلاثة أشكال للمقتطف كما يرسلها المصدر فعلاً (تحقّق حيّ 2026-11-02): بادئة
    // قسم ثم العنوان، أو العنوان أولاً ثم المتن، أو مقتطف مسحوق من صفحة الخبر
    // بأزرار الموقع. أيّها ظهر لا يُعرض عنوان مكرّراً ولا «0 اخبار محلية».
    excerpt: index === 1
      ? `خبر الاختبار ${index + 1} مقتطف الخبر ${index + 1}`
      : index === 2
        ? `ك ا كل العرب محاكم وجنائيات حجم الخط A- A+ مقتطف الخبر ${index + 1}`
        : `0 اخبار محلية خبر الاختبار ${index + 1} مقتطف الخبر ${index + 1}`,
    // صورة كل خبر ثانٍ غائبة — الصورة اختيارية في العقد، لا شرطاً لعرض الخبر.
    image: index % 2 === 0 ? `https://radio.ktra-pro.tech/news/${index + 1}.jpg` : null,
    url: `https://radio.ktra-pro.tech/news/${900 + index}`,
    published_at: new Date(Date.UTC(2026, 9, 27, 8, 0, 0) - index * 3600000).toISOString(),
    is_breaking: index === 0,
    category: { id: 3, name: 'أخبار المنطقة' }
  }));
  const KATRA_FIXTURE_MALFORMED = [
    { id: 'ليس معرّفاً', title: 'عنوان بلا معرّف', excerpt: null, image: null, url: null, published_at: null, is_breaking: false, category: null },
    { id: 1001, title: '   ', excerpt: 'عنوان فارغ', image: null, url: null, published_at: null, is_breaking: false, category: null }
  ];

  /** ما وصل إلى المصدر فعلاً — كل نداء يُسجَّل للتحقق من `limit`/`offset`/`areas`. */
  const katraRequests = [];
  let katraFailing = false;

  const katraServer = http.createServer((req, res) => {
    const requestUrl = new URL(req.url, 'http://127.0.0.1');
    if (requestUrl.pathname !== '/api/news.php') {
      res.writeHead(404, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ ok: false }));
      return;
    }
    if (katraFailing) {
      res.writeHead(500, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ ok: false, message: 'down' }));
      return;
    }

    katraRequests.push({ path: requestUrl.pathname, search: requestUrl.searchParams });
    res.setHeader('Content-Type', 'application/json');

    const detailId = requestUrl.searchParams.get('id');
    if (detailId !== null) {
      const found = KATRA_FIXTURE_ITEMS.find(item => item.id === Number(detailId));
      // المصدر الحقيقي يردّ 404 بجسم JSON لخبر غير موجود (تحقّق حيّ 2026-11-02)؛
      // هذا الحارس يقلّده بدل `{ ok: true, item: null }` كي لا يمرّ 502
      // «مصدر متعطّل» مكان 404 «الخبر غير موجود» بلا أن يمسكه اختبار.
      if (!found) {
        res.writeHead(404, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ ok: false, error: 'not_found', message: 'الخبر غير موجود' }));
        return;
      }
      res.end(JSON.stringify({
        ok: true,
        item: { ...found, author_name: 'محرّر كترا', body_text: 'الفقرة الأولى من الخبر.\nحجم الخط A- A+ ✓تم النسخ ⤴واتساب\nالفقرة الثانية من الخبر.' }
      }));
      return;
    }

    const limit = Number(requestUrl.searchParams.get('limit') || 50);
    const offset = Number(requestUrl.searchParams.get('offset') || 0);
    const all = [...KATRA_FIXTURE_ITEMS, ...KATRA_FIXTURE_MALFORMED];
    res.end(JSON.stringify({
      ok: true,
      items: all.slice(offset, offset + limit),
      has_more: offset + limit < all.length
    }));
  });
  await new Promise(resolve => katraServer.listen(0, '127.0.0.1', resolve));
  process.env.KATRA_NEWS_BASE_URL = `http://127.0.0.1:${katraServer.address().port}`;
  process.env.KATRA_NEWS_CACHE_TTL_MS = '0';

  const lastKatraRequest = () => katraRequests[katraRequests.length - 1];

  await test('GET /api/news يشتقّ منطقة المحافظة من اسمها ويعيد عقد القائمة كاملاً (وجهة «خدماتنا»)', async () => {
    katraFailing = false;
    const { status, body } = await api('GET', '/api/news?limit=50&offset=0', { region: newsRegionRow.id });

    assert.strictEqual(status, 200, JSON.stringify(body));
    assert.strictEqual(body.success, true);
    assert.strictEqual(body.region_id, newsRegionRow.id);
    assert.strictEqual(body.region_name, SEED_REGION.name, 'اسم المحافظة هو ما يعرضه هيدر الشاشة');
    assert.strictEqual(body.area, 'النقب', '«النقب» مفتاحها عربي في NEWS_AREA_BY_REGION_NAME — مفاتيح المصدر عربية');
    assert.strictEqual(body.general, false);
    assert.strictEqual(body.items.length, 50, 'عنصران مشوّهان يُسقطان بصمت، والصفحة تبقى خمسين سليماً');
    assert.strictEqual(body.has_more, true);

    const sent = lastKatraRequest();
    assert.ok(sent, 'the route must actually call the source');
    assert.strictEqual(sent.search.get('areas'), 'النقب');
    assert.strictEqual(sent.search.get('area'), 'النقب', 'المنطقة المحدَّدة تُمرَّر في المعاملين');
    assert.strictEqual(sent.search.get('limit'), '50');
    assert.strictEqual(sent.search.get('offset'), '0');

    const first = body.items[0];
    assert.strictEqual(first.id, 900);
    assert.strictEqual(first.is_breaking, true, 'الخبر العاجل يصل منطقياً true');
    assert.ok(first.image.startsWith('https://'), 'الصورة المطلقة تعبر كما هي');
    assert.ok(/Z$/.test(first.published_at), 'published_at يخرج ISO 8601 UTC');
    assert.deepStrictEqual(first.category, { id: 3, name: 'أخبار المنطقة' });
    assert.strictEqual(body.items[1].image, null, 'الخبر بلا صورة يبقى بلا صورة');
    assert.strictEqual(body.items[1].is_breaking, false);
    assert.strictEqual(first.excerpt, 'مقتطف الخبر 1', 'بادئة المصدر («0 اخبار محلية») وعنوانه لا يتكرّران في المقتطف');
    assert.strictEqual(body.items[1].excerpt, 'مقتطف الخبر 2', 'والشكل الآخر — عنوان في أوّل المقتطف — يُسقط عنوانه أيضاً');
    assert.strictEqual(body.items[2].excerpt, null, 'مقتطف مسحوق بأزرار الموقع يُسقط كاملاً بدل عرض زخرفته');
    assert.ok(!body.items.some(item => item.id === 1001), 'خبر بلا عنوان يُسقَط');
  });

  await test('general=1 يجبر الوجه العام بلا منطقة، ولا يرسل area للمصدر', async () => {
    const { status, body } = await api('GET', '/api/news?limit=50&general=1', { region: newsRegionRow.id });

    assert.strictEqual(status, 200, JSON.stringify(body));
    assert.strictEqual(body.area, 'general');
    assert.strictEqual(body.general, true);
    assert.strictEqual(body.region_name, SEED_REGION.name, 'اسم المحافظة يبقى في الرد حتى في الوجه العام');

    const sent = lastKatraRequest();
    assert.strictEqual(sent.search.get('areas'), 'general');
    assert.strictEqual(sent.search.get('area'), null, 'الوجه العام لا يقيّد بـarea');
  });

