  console.log('\n«بالرابط فقط» — مناسبة مخفيّة تُفتح برابطها وبمعرّفها (تذكرة #166)');

  const visibilityListener = await createDirectUser('مستمع مناسبة بالرابط فقط');
  const visibilityEventIds = [];
