  await test('حذف الدعوة لا يحذف الجواب: invite_id يصير NULL والصفّ يبقى في «مين جاي»', async () => {
    const before = await api('GET', `/api/events/${inviteEventId}/invites`, { token: inviteOwner.token });
    assert.strictEqual(before.body.invites.length, inviteCount, 'set up: the three invites are still there');

    const removed = await api('DELETE', `/api/events/${inviteEventId}/invites/${firstInvite.id}`, {
      token: inviteOwner.token
    });
    assert.strictEqual(removed.status, 200, removed.body.message);
    assert.ok(String(removed.body.message).includes('حذف'), 'the success message is Arabic, like every other one');

    const after = await api('GET', `/api/events/${inviteEventId}/invites`, { token: inviteOwner.token });
    assert.strictEqual(after.body.invites.length, inviteCount - 1, 'the invite itself is gone');
    assert.ok(
      !after.body.invites.some(invite => invite.id === firstInvite.id),
      'and it is that one that went'
    );

    const row = await db.queryOne(
      'SELECT invite_id, guest_name, response FROM event_rsvps WHERE event_id = ? AND guest_phone = ?',
      [inviteEventId, INVITE_GUEST_PHONE]
    );
    assert.ok(row, 'the answer it collected survives the delete');
    assert.strictEqual(row.invite_id, null, 'ON DELETE SET NULL detaches it — no cascade to the answer');
    assert.strictEqual(row.guest_name, INVITE_GUEST_NAME, 'with its name intact');
    assert.strictEqual(row.response, 'yes', 'and its answer intact');

    const list = await api('GET', `/api/events/${inviteEventId}/rsvps`, { token: inviteOwner.token });
    const entry = list.body.rsvps.find(rsvp => rsvp.name === INVITE_GUEST_NAME);
    assert.ok(entry, '«مين جاي» still lists it');
    assert.strictEqual(entry.invite, null, 'as a plain answer — the invite it came from no longer exists');

    // والحذف الثاني للدعوة نفسها 404، لا حذف صامت.
    const twice = await api('DELETE', `/api/events/${inviteEventId}/invites/${firstInvite.id}`, {
      token: inviteOwner.token
    });
    assert.strictEqual(twice.status, 404);
  });

  await test('قائمة أسماء فارغة أو زائدة أو اسم فارغ: 400 عربية بلا صفّ جديد', async () => {
    const before = await api('GET', `/api/events/${inviteEventId}/invites`, { token: inviteOwner.token });

    for (const [label, names] of [
      ['قائمة فارغة', []],
      ['أسماء فارغة بعد القصّ', ['   ', '']],
      ['أكثر من السقف', Array.from({ length: INVITE_BATCH_MAX + 1 }, (_, index) => `ضيف ${index}`)],
      ['أطول من 120 حرفاً', ['ا'.repeat(121)]]
    ]) {
      const res = await api('POST', `/api/events/${inviteEventId}/invites`, {
        token: inviteOwner.token, body: { names }
      });
      assert.strictEqual(res.status, 400, `${label}: 400`);
      assert.ok(
        /[\u0600-\u06FF]/.test(String(res.body.message || '')),
        `${label}: an Arabic message, not an English one — got: ${res.body.message}`
      );
    }

    // الجسم بلا `names` أصلاً: نفس الرفض لا استثناء.
    const shapeless = await api('POST', `/api/events/${inviteEventId}/invites`, {
      token: inviteOwner.token, body: { names: 'سالم' }
    });
    assert.strictEqual(shapeless.status, 400, 'a string instead of an array is a malformed request');

    const after = await api('GET', `/api/events/${inviteEventId}/invites`, { token: inviteOwner.token });
    assert.strictEqual(after.body.invites.length, before.body.invites.length, 'no refused request wrote a row');
  });

  // تنظيف القسم: المناسبات تسقط ومَعها دعواتها وأجوبتها بـON DELETE CASCADE،
  // والمستخدمون (وأدمن البلدتين معهم بـCASCADE على admin_towns).
  for (const id of inviteEventIds) {
    await db.execute('DELETE FROM notifications WHERE event_id = ?', [id]);
    await db.execute('DELETE FROM events WHERE id = ?', [id]);
  }
  await db.execute(
    'DELETE FROM users WHERE id IN (?, ?, ?, ?)',
    [inviteOwner.id, inviteStranger.id, inviteAdminInTown.id, inviteAdminOutOfTown.id]
  );

  console.log('\n«مناسبة كبرى» — الإبراز حتى تاريخ، وسقف المحافظة، وترتيب التغذية (#171)');

  /**
   * قسم #171: محافظة ثانية وبلدة فيها وأدمن مقيَّد بها، ومناسبات مبرزة في
   * محافظة النقب. كل صفّ يُنشأ هنا يُحذف في نهاية القسم.
   *
   * البحث الفريد (`featuredStamp`) هو ما يجعل التأكيدات مستقلة عن بقية صفوف
   * قاعدة التطوير المشتركة: تغذية هذا القسم وحدها هي ما يُقرأ، فلا يعتمد
   * «الأول» على مناسبة قديمة مبرزة من تشغيل سابق.
   */
  const featuredStamp = `كبرى${Date.now()}`;
  const featuredCleanup = { eventIds: [], townIds: [], regionIds: [], userIds: [] };

  const { insertId: featuredOtherRegionId } = await db.execute(
    `INSERT INTO regions (name, latitude, longitude, map_zoom, position, is_active)
     VALUES (?, 32.4, 35.1, 9, 97, 1)`,
    [`محافظة إبراز ${featuredStamp}`]
  );
  featuredCleanup.regionIds.push(featuredOtherRegionId);

  const featuredOtherTown = `بلدة إبراز ${featuredStamp}`;
  const { insertId: featuredOtherTownId } = await db.execute(
    `INSERT INTO towns (region_id, name, latitude, longitude, position, is_active)
     VALUES (?, ?, 32.4, 35.1, 1, 1)`,
    [featuredOtherRegionId, featuredOtherTown]
  );
  featuredCleanup.townIds.push(featuredOtherTownId);

  // أدمن بلدة واحدة في المحافظة الثانية: نطاقه ضيّق فعلاً، فمناسبة النقب
  // خارجه — وهو ما يثبت 404 لا 403.
  const featuredOtherAdminPhone = `05${Math.floor(10000000 + Math.random() * 89999999)}`;
  const { insertId: featuredOtherAdminId } = await db.execute(
    `INSERT INTO users (phone_number, full_name, pin_code, clan_town, role) VALUES (?, ?, ?, ?, 'admin')`,
    [featuredOtherAdminPhone, 'أدمن محافظة الإبراز', bcrypt.hashSync('1234', config.bcryptRounds), featuredOtherTown]
  );
  featuredCleanup.userIds.push(featuredOtherAdminId);
  await db.execute('INSERT INTO admin_towns (user_id, town) VALUES (?, ?)', [featuredOtherAdminId, featuredOtherTown]);
  const featuredOtherAdminToken = signToken({
    id: featuredOtherAdminId,
    phone_number: featuredOtherAdminPhone,
    full_name: 'أدمن محافظة الإبراز',
    role: 'admin'
  }, '1h');

  /** ينشر مناسبة معتمدة (سوبر أدمن) باسم بحث فريد في المحافظة المطلوبة. */
  async function publishFeaturedEvent({ dayOffset, town = 'حورة', label }) {
    const created = await api('POST', '/api/events', {
      token: superAdminToken,
      body: weddingEventBody({
        honorees: [{ name: `${featuredStamp} ${label}` }],
        town,
        event_date: addDaysToDate(schedulerToday, dayOffset),
        location_name: `قاعة ${featuredStamp} ${label}`
      })
    });
    assert.strictEqual(created.status, 201, created.body.message);
    assert.strictEqual(created.body.status, 'approved', 'a super_admin publish goes live immediately');
    featuredCleanup.eventIds.push(created.body.eventId);
    return created.body.eventId;
  }

  /** تغذية محافظة النقب، مقيَّدة بمناسبات هذا القسم وحدها (البحث الفريد). */
  async function featuredFeed() {
    const { status, body } = await api(
      'GET',
      `/api/events?upcoming=1&limit=100&search=${encodeURIComponent(featuredStamp)}`,
      { region: defaultRegionId }
    );
    assert.strictEqual(status, 200);
    return body;
  }

  const featuredIds = [];
  let featuredFourthId = 0;
  let featuredOtherRegionEventId = 0;
  const featuredUntil = addDaysToDate(schedulerToday, 20);

  await test('PATCH /api/admin/events/:id/featured يكتب featured_until، والمبرزة تتصدّر تغذية محافظتها بـis_featured منطقية', async () => {
    featuredIds.push(await publishFeaturedEvent({ dayOffset: 5, label: 'الأولى' }));
    featuredIds.push(await publishFeaturedEvent({ dayOffset: 6, label: 'الثانية' }));
    featuredIds.push(await publishFeaturedEvent({ dayOffset: 7, label: 'الثالثة' }));

    const before = await featuredFeed();
    assert.deepStrictEqual(before.events.map(event => event.id), featuredIds, 'before featuring, the feed is date order');
    assert.deepStrictEqual(
      before.events.map(event => event.is_featured),
      [false, false, false],
      'and every row says is_featured: false'
    );

    const patched = await api('PATCH', `/api/admin/events/${featuredIds[2]}/featured`, {
      token: superAdminToken,
      body: { featured_until: featuredUntil }
    });
    assert.strictEqual(patched.status, 200, patched.body.message);
    assert.strictEqual(patched.body.event.featured_until, featuredUntil, 'the route answers with the stored date');
    assert.strictEqual(patched.body.event.is_featured, true, 'and with the computed is_featured');

    const stored = await db.queryOne('SELECT featured_until FROM events WHERE id = ?', [featuredIds[2]]);
    assert.strictEqual(stored.featured_until, featuredUntil, 'the DATE column stores the picked day as YYYY-MM-DD');

    const after = await featuredFeed();
    assert.strictEqual(after.events[0].id, featuredIds[2], 'the featured event tops its own governorate feed');
    assert.strictEqual(after.events[0].is_featured, true, 'is_featured is boolean true on the featured row');
    assert.strictEqual(typeof after.events[1].is_featured, 'boolean', 'and a boolean on every other row');
    assert.strictEqual(after.events[1].is_featured, false, 'a plain row is is_featured: false');
    assert.deepStrictEqual(
      after.events.slice(1).map(event => event.id),
      [featuredIds[0], featuredIds[1]],
      'the rows around it keep their existing order'
    );
  });

  await test('الرابعة النشِطة في المحافظة نفسها 409 عربية، والرابعة في محافظة أخرى تُقبل', async () => {
    for (const id of featuredIds.slice(0, 2)) {
      const res = await api('PATCH', `/api/admin/events/${id}/featured`, {
        token: superAdminToken,
        body: { featured_until: featuredUntil }
      });
      assert.strictEqual(res.status, 200, `featured ${id}: ${res.body.message}`);
    }
    const activeRows = await db.query(
      `SELECT id FROM events
        WHERE region_id = ? AND featured_until IS NOT NULL AND featured_until >= CURDATE()
          AND id IN (?, ?, ?)`,
      [defaultRegionId, ...featuredIds]
    );
    assert.strictEqual(activeRows.length, 3, 'three active featured rows now sit in this governorate');

    featuredFourthId = await publishFeaturedEvent({ dayOffset: 8, label: 'الرابعة' });
    const refused = await api('PATCH', `/api/admin/events/${featuredFourthId}/featured`, {
      token: superAdminToken,
      body: { featured_until: featuredUntil }
    });
    assert.strictEqual(refused.status, 409, 'a fourth active featured event in one governorate is refused');
    assert.ok(/[\u0600-\u06FF]/.test(refused.body.message), `the refusal is Arabic: ${refused.body.message}`);
    assert.ok(refused.body.message.includes('مناسبات'), 'and names what hit its ceiling');
    assert.strictEqual(
      (await db.queryOne('SELECT featured_until FROM events WHERE id = ?', [featuredFourthId])).featured_until,
      null,
      'and nothing was written for the refused event'
    );

    // محافظة أخرى لا تتأثّر بسقف هذه: الإبراز فيها يمرّ.
    featuredOtherRegionEventId = await publishFeaturedEvent({
      dayOffset: 9, town: featuredOtherTown, label: 'محافظة أخرى'
    });
    const accepted = await api('PATCH', `/api/admin/events/${featuredOtherRegionEventId}/featured`, {
      token: superAdminToken,
      body: { featured_until: featuredUntil }
    });
    assert.strictEqual(accepted.status, 200, 'another governorate is not affected by this one\'s ceiling');

    const regionAFeed = await featuredFeed();
    assert.ok(
      !regionAFeed.events.some(event => event.id === featuredOtherRegionEventId),
      'and the featured event of another governorate never enters this one\'s feed'
    );
  });

  await test('إلغاء الإبراز بـnull يعيد الصفّ لمكانه ويُفرّغ مقعد السقف', async () => {
    // الملغى هو **الأقدم** (`featuredIds[0]`، وأول التغذية قبل الإلغاء)، لا
    // الأخير: إلغاء الأخير يجعله آخراً في ترتيب التاريخ وحده، فيبقى الشرط
    // صحيحاً في ثلاثة عوالم — الإلغاء يعمل، أو ترتيب الإبراز مفقود، أو الإلغاء
    // لا يكتب شيئاً — فلا يقيس واحداً منها. أما الأقدم فلا يهبط خلف
    // `featuredIds[1]` إلا إذا كُتب الإلغاء فعلاً **و** عمل ترتيب الإبراز معاً.
    const cleared = await api('PATCH', `/api/admin/events/${featuredIds[0]}/featured`, {
      token: superAdminToken,
      body: { featured_until: null }
    });
    assert.strictEqual(cleared.status, 200, cleared.body.message);
    assert.strictEqual(cleared.body.event.featured_until, null, 'null clears the column');
    assert.strictEqual(cleared.body.event.is_featured, false, 'and the computed flag with it');

    const afterCancel = await featuredFeed();
    const cancelledAt = afterCancel.events.findIndex(event => event.id === featuredIds[0]);
    const stillFeaturedAt = afterCancel.events.findIndex(event => event.id === featuredIds[1]);
    assert.ok(
      cancelledAt > stillFeaturedAt,
      `the cancelled leading event must fall behind the still-featured one — got ${cancelledAt} vs ${stillFeaturedAt}`
    );

    const freed = await api('PATCH', `/api/admin/events/${featuredFourthId}/featured`, {
      token: superAdminToken,
      body: { featured_until: featuredUntil }
    });
    assert.strictEqual(freed.status, 200, 'the seat freed by the cancel accepts the fourth');
  });

  await test('تاريخ انتهى (أمس) لا يُبرز: is_featured false والصفّ لا يتصدّر', async () => {
    const yesterday = addDaysToDate(schedulerToday, -1);
    const expired = await api('PATCH', `/api/admin/events/${featuredIds[0]}/featured`, {
      token: superAdminToken,
      body: { featured_until: yesterday }
    });
    assert.strictEqual(expired.status, 200, 'a past date is accepted — it simply means "not featured"');
    assert.strictEqual(expired.body.event.is_featured, false, 'the computed flag is false on a past date');

    const feed = await featuredFeed();
    const row = feed.events.find(event => event.id === featuredIds[0]);
    assert.ok(row, 'the event is still in the feed — featuring never hides anything');
    assert.strictEqual(row.is_featured, false, 'the row says is_featured: false after its date passed');
    assert.notStrictEqual(feed.events[0].id, featuredIds[0], 'and it no longer tops the feed');
  });

  await test('أدمن خارج نطاق المناسبة يُردّ 404 لا 403 ولا يُكتب شيء، وأدمن داخله يمرّ', async () => {
    const target = featuredIds[1];
    const before = await db.queryOne('SELECT featured_until FROM events WHERE id = ?', [target]);
    const refused = await api('PATCH', `/api/admin/events/${target}/featured`, {
      token: featuredOtherAdminToken,
      body: { featured_until: addDaysToDate(schedulerToday, 30) }
    });
    assert.strictEqual(refused.status, 404, 'an out-of-scope admin gets 404, never 403');
    assert.ok(/[\u0600-\u06FF]/.test(refused.body.message), `the refusal is Arabic: ${refused.body.message}`);
    assert.strictEqual(
      (await db.queryOne('SELECT featured_until FROM events WHERE id = ?', [target])).featured_until,
      before.featured_until,
      'and the row is untouched'
    );

    const own = await api('PATCH', `/api/admin/events/${featuredOtherRegionEventId}/featured`, {
      token: featuredOtherAdminToken,
      body: { featured_until: addDaysToDate(schedulerToday, 30) }
    });
    assert.strictEqual(own.status, 200, 'the same admin may feature an event inside its own town');

    const normalUser = await createDirectUser('مستخدم مسار الإبراز');
    featuredCleanup.userIds.push(normalUser.id);
    const asUser = await api('PATCH', `/api/admin/events/${target}/featured`, {
      token: normalUser.token,
      body: { featured_until: addDaysToDate(schedulerToday, 30) }
    });
    assert.strictEqual(asUser.status, 403, 'a regular user never reaches an admin route');
  });

  await test('تاريخ الإبراز يُتحقَّق في validate.js: صيغة خاطئة 400، وغياب المفتاح 400 لا إلغاء صامت', async () => {
    const target = featuredIds[1];
    const bad = await api('PATCH', `/api/admin/events/${target}/featured`, {
      token: superAdminToken,
      body: { featured_until: '2026-13-45' }
    });
    assert.strictEqual(bad.status, 400, 'a malformed date is refused');
    assert.ok(bad.body.message.includes('YYYY-MM-DD'), `the shared validate.js date message: ${bad.body.message}`);

    const missing = await api('PATCH', `/api/admin/events/${target}/featured`, {
      token: superAdminToken,
      body: {}
    });
    assert.strictEqual(missing.status, 400, 'an absent key is a bad date, never a silent cancel');
    assert.strictEqual(
      (await db.queryOne('SELECT featured_until FROM events WHERE id = ?', [target])).featured_until,
      featuredUntil,
      'neither refusal touched the stored date'
    );
  });

  await test('الترقيم لا ينكسر: COUNT(*) يعدّ الصفوف نفسها، والمبرزة تظهر مرة واحدة عبر الصفحات', async () => {
    const all = await featuredFeed();
    const first = await api(
      'GET',
      `/api/events?upcoming=1&limit=2&page=1&search=${encodeURIComponent(featuredStamp)}`,
      { region: defaultRegionId }
    );
    assert.strictEqual(first.status, 200);
    const second = await api(
      'GET',
      `/api/events?upcoming=1&limit=2&page=2&search=${encodeURIComponent(featuredStamp)}`,
      { region: defaultRegionId }
    );

    const total = first.body.pagination.total;
    assert.strictEqual(
      total, all.events.length,
      'COUNT(*) counts exactly the rows the WHERE clause selects — the featured ordering adds no filter'
    );
    assert.strictEqual(first.body.pagination.totalPages, Math.ceil(total / 2));
    assert.strictEqual(first.body.events.length, 2);
    assert.strictEqual(second.body.events.length, Math.min(2, total - 2));

    const pagedIds = [...first.body.events, ...second.body.events].map(event => event.id);
    assert.strictEqual(new Set(pagedIds).size, pagedIds.length, 'no row is repeated across pages');
    assert.deepStrictEqual(pagedIds, all.events.slice(0, pagedIds.length).map(event => event.id), 'and the pages follow the ordered list exactly');
    assert.strictEqual(first.body.events[0].is_featured, true, 'the featured row still leads page one');
  });

  await test('السقف يحرس الانتقال إلى نشِط وحده: تاريخ مستقبلي لصفّ غير مبرز 409، وتاريخ منقضٍ له 200', async () => {
    // هذه المحافظة كاملة الآن بثلاثة نشِطة (f1، f2، f4)، و`featuredIds[0]` غير
    // مبرز (تاريخه أمس من التأكيد السابق). السقف يجب أن يفرق بين الحالتين:
    // تاريخ مستقبلي **يزيد** النشِط رابعاً فيُردّ، وتاريخ منقضٍ **لا يزيد**
    // شيئاً فيمرّ — وإلا لتعذّر على الأدمن سحب إبرازٍ أو كتابة تاريخ ماضٍ في
    // محافظة ممتلئة. فرضُ السقف على كل قيمة غير `null` يُسقط هذا التأكيد عند
    // طلب التاريخ المنقضي بـ409.
    const notFeaturedId = featuredIds[0];
    const activeNow = await db.queryOne(
      `SELECT COUNT(*) AS total FROM events
        WHERE region_id = ? AND featured_until IS NOT NULL AND featured_until >= CURDATE()
          AND id IN (?, ?, ?, ?)`,
      [defaultRegionId, ...featuredIds, featuredFourthId]
    );
    assert.strictEqual(Number(activeNow.total), 3, 'the governorate is full before this check');

    const before = (await db.queryOne('SELECT featured_until FROM events WHERE id = ?', [notFeaturedId])).featured_until;
    const future = await api('PATCH', `/api/admin/events/${notFeaturedId}/featured`, {
      token: superAdminToken,
      body: { featured_until: addDaysToDate(schedulerToday, 25) }
    });
    assert.strictEqual(future.status, 409, 'a future date on a non-featured row would be a fourth active one');
    assert.strictEqual(
      (await db.queryOne('SELECT featured_until FROM events WHERE id = ?', [notFeaturedId])).featured_until,
      before,
      'and nothing was written for the refused row'
    );

    const expiredDate = addDaysToDate(schedulerToday, -3);
    const expired = await api('PATCH', `/api/admin/events/${notFeaturedId}/featured`, {
      token: superAdminToken,
      body: { featured_until: expiredDate }
    });
    assert.strictEqual(expired.status, 200, 'a past date adds nothing to the active set, so the ceiling cannot refuse it');
    assert.strictEqual(expired.body.event.featured_until, expiredDate, 'and the picked day is stored as given');
    assert.strictEqual(expired.body.event.is_featured, false, 'while the computed flag stays false');
  });

  await test('طلبان متزامنان لإبراز مناسبتين مختلفتين بمقعد حرّ واحد: أحدهما 200 والآخر 409، والنشِطة لا تتجاوز السقف', async () => {
    // العيب المسمّى في تذكرة #171: العدّ ثم `UPDATE` كانا معاملتين منفصلتين،
    // فطلبان متزامنان على مناسبتين مختلفتين في المحافظة نفسها يقرآن العدد
    // نفسه (2 هنا) فيمرّان معاً — فتصير المحافظة بأربع نشِطة والسقف ثلاثة.
    // القفل على صفّ المحافظة هو ما يجعل الفحص والكتابة وحدة واحدة، فينتظر
    // الثاني إفراج الأول ثم يعدّ فيرى المقعد محجوزاً ويُردّ 409.
    //
    // المقعد الحرّ الواحد يُصنع بإلغاء `featuredIds[1]`: النشِط الباقي بعد
    // الإلغاء `featuredIds[2]` و`featuredFourthId` (اثنان)، فيبقى مقعد واحد.
    const seatFreed = await api('PATCH', `/api/admin/events/${featuredIds[1]}/featured`, {
      token: superAdminToken,
      body: { featured_until: null }
    });
    assert.strictEqual(seatFreed.status, 200, seatFreed.body.message);

    const racers = [
      await publishFeaturedEvent({ dayOffset: 10, label: 'المتسابقة الأولى' }),
      await publishFeaturedEvent({ dayOffset: 11, label: 'المتسابقة الثانية' })
    ];

    const activeQuery = `SELECT id FROM events
        WHERE region_id = ? AND featured_until IS NOT NULL AND featured_until >= CURDATE()
          AND id IN (?, ?, ?, ?, ?, ?)`;
    const activeParams = [defaultRegionId, ...featuredIds, featuredFourthId, ...racers];

    const before = await db.query(activeQuery, activeParams);
    assert.strictEqual(before.length, 2, 'مقعد واحد حرّ في المحافظة قبل السباق');

    // الطلبان يُطلقان معاً (لا واحداً بعد الآخر): هذا هو التوازي الذي كان
    // الاختبار السابق — طلباً بعد طلب — لا يستطيع كشفه.
    const [first, second] = await Promise.all(racers.map(id => api('PATCH', `/api/admin/events/${id}/featured`, {
      token: superAdminToken,
      body: { featured_until: featuredUntil }
    })));

    assert.deepStrictEqual(
      [first.status, second.status].sort((a, b) => a - b),
      [200, 409],
      `واحد فقط يأخذ المقعد الحرّ والآخر 409: ${first.status} / ${second.status}`
    );
    assert.ok(/[\u0600-\u06FF]/.test((first.status === 409 ? first : second).body.message), 'ورفض السباق عربي كالقائم');

    const activeRows = await db.query(activeQuery, activeParams);
    assert.ok(
      activeRows.length <= 3,
      `السباق لا يتجاوز سقف المحافظة: ${activeRows.length} نشِطة — ${JSON.stringify(activeRows)}`
    );
  });

  // تنظيف قسم الإبراز: المناسبات، ثم المستخدمون (وadmin_towns معهم)، ثم البلدة
  // ثم المحافظة — بترتيب المفاتيح الأجنبية.
  for (const id of featuredCleanup.eventIds) {
    await api('DELETE', `/api/admin/events/${id}`, { token: superAdminToken });
  }
  for (const id of featuredCleanup.userIds) await db.execute('DELETE FROM users WHERE id = ?', [id]);
  for (const id of featuredCleanup.townIds) await db.execute('DELETE FROM towns WHERE id = ?', [id]);
  for (const id of featuredCleanup.regionIds) await db.execute('DELETE FROM regions WHERE id = ?', [id]);

  console.log('\nشريط الإحصائيات في الرئيسية — عدّ القادم لكل محافظة وكاشه (تذكرة #172)');

  /**
   * محافظة خاصة بهذا القسم وبلدة تحتها: العدّاد يُقرأ من الشريط بمعرّف
   * المحافظة، فصفوف قسم آخر في «النقب» المشتركة لا تُفسد الرقم. وكل صفّ
   * يُنشأ هنا يُحذف في نهاية القسم بترتيب المفاتيح الأجنبية.
   */
  const statsStamp = `إحصاء${Date.now()}`;
  const statsRegionName = `محافظة ${statsStamp}`;
  const statsTownName = `بلدة ${statsStamp}`;
  const statsCleanup = { eventIds: [], townIds: [], regionIds: [] };

  const { insertId: statsRegionId } = await db.execute(
    `INSERT INTO regions (name, latitude, longitude, map_zoom, position, is_active)
     VALUES (?, 31.2, 34.8, 9, 98, 1)`,
    [statsRegionName]
  );
  statsCleanup.regionIds.push(statsRegionId);

  const { insertId: statsTownId } = await db.execute(
    `INSERT INTO towns (region_id, name, latitude, longitude, position, is_active)
     VALUES (?, ?, 31.2, 34.8, 1, 1)`,
    [statsRegionId, statsTownName]
  );
  statsCleanup.townIds.push(statsTownId);

  // التواريخ من `CURDATE()` الذي يقرأه الخادم نفسه (انظر `schedulerToday`):
  // «قادم» و«منتهٍ» هنا يجب أن يكونا كذلك بالنسبة للشرط الذي يُنفَّذ فعلاً.
  const STATS_UPCOMING_DAY = addDaysToDate(schedulerToday, 12);
  const STATS_ENDED_DAY = addDaysToDate(schedulerToday, -4);

  /** ينشر مناسبة في محافظة القسم (سوبر أدمن: تنشر فوراً) ويعيد معرّفها. */
  async function publishStatsEvent({ label, day = STATS_UPCOMING_DAY, overrides = {} }) {
    const created = await api('POST', '/api/events', {
      token: superAdminToken,
      body: weddingEventBody({
        honorees: [{ name: `${statsStamp} ${label}` }],
        town: statsTownName,
        event_date: day,
        location_name: `قاعة ${statsStamp} ${label}`,
        ...overrides
      })
    });
    assert.strictEqual(created.status, 201, created.body.message);
    statsCleanup.eventIds.push(created.body.eventId);
    return created.body.eventId;
  }

  /**
   * صفّ محافظة القسم في الشريط **بعد تفريغ الكاش**: هذا القسم يقيس العدّ
   * الحقيقي، ونسخةٌ عمرها ثوانٍ من طلب سابق كانت ستُنجح تأكيدات «لم يتغيّر
   * الرقم» لسبب آخر غير الذي تحمله أسماؤها.
   */
  async function statsRegionRow() {
    statsService.clearTickerCache();
    const { status, body } = await api('GET', '/api/stats/ticker');
    assert.strictEqual(status, 200, body.message);
    return (body.regions || []).find(region => region.region_id === statsRegionId) || null;
  }

  await test('GET /api/stats/ticker عام — كل صفّ { region_id, name, upcoming_count }، وtotal مجموع الصفوف، وupdated_at لحظة', async () => {
    await publishStatsEvent({ label: 'الأولى' });
    await publishStatsEvent({ label: 'الثانية' });

    statsService.clearTickerCache();
    const { status, body } = await api('GET', '/api/stats/ticker');
    assert.strictEqual(status, 200, body.message);
    assert.ok(Array.isArray(body.regions) && body.regions.length > 0, 'الشريط يعيد محافظات');
    for (const region of body.regions) {
      assert.deepStrictEqual(
        Object.keys(region).sort(),
        ['name', 'region_id', 'upcoming_count'],
        `صفّ المحافظة لا يحمل إلا حقوله الثلاثة: ${JSON.stringify(region)}`
      );
      assert.strictEqual(typeof region.region_id, 'number', 'region_id رقم — يطابق GET /api/towns');
      assert.strictEqual(typeof region.name, 'string', 'name اسم المحافظة كما في جدول regions');
      assert.strictEqual(typeof region.upcoming_count, 'number', 'upcoming_count رقم لا نصّ');
    }
    assert.strictEqual(
      body.total,
      body.regions.reduce((sum, region) => sum + region.upcoming_count, 0),
      'total مجموع الأعداد المعروضة نفسها — لا استعلام ثانٍ يخالفه'
    );
    assert.ok(!Number.isNaN(Date.parse(body.updated_at)), `updated_at لحظة مقروءة، وصل "${body.updated_at}"`);

    const mine = body.regions.find(region => region.region_id === statsRegionId);
    assert.ok(mine, 'المحافظة النشطة لهذا القسم لها صفّ في الشريط');
    assert.strictEqual(mine.name, statsRegionName, 'وباسمها كما في القاعدة');
    assert.strictEqual(mine.upcoming_count, 2, 'ومناسبتاها المعتمدتان القادمتان وحدهما');
  });

  await test('عدّ المحافظة يطابق القائمة العامة نفسها — المعلّقة والمجدولة لا تُعدّان', async () => {
    // معلّقة: ينشرها مستخدم عادي فتبقى في الطابور، ولا تظهر في أي قائمة.
    const pending = await api('POST', '/api/events', {
      token: userToken,
      body: weddingEventBody({
        honorees: [{ name: `${statsStamp} المعلّقة` }],
        town: statsTownName,
        event_date: STATS_UPCOMING_DAY,
        location_name: `قاعة ${statsStamp} المعلّقة`
      })
    });
    assert.strictEqual(pending.status, 201, pending.body.message);
    assert.strictEqual(pending.body.status, 'pending', 'المناسبة فعلت الطابور حقاً');
    statsCleanup.eventIds.push(pending.body.eventId);

    // مجدولة: معتمدة وقادمة، لكن النشر لم يبلغ موعده (#167).
    const scheduledId = await publishStatsEvent({
      label: 'المجدولة',
      overrides: { publish_at: `${addDaysToDate(schedulerToday, 2)}T09:00` }
    });
    const scheduledRow = await db.queryOne('SELECT status, publish_at FROM events WHERE id = ?', [scheduledId]);
    assert.strictEqual(scheduledRow.status, 'approved', 'المجدولة معتمدة — الغياب من الظهور لا من الحالة');

    const feed = await api(
      'GET',
      `/api/events?upcoming=1&limit=100&search=${encodeURIComponent(statsStamp)}`,
      { region: statsRegionId }
    );
    assert.strictEqual(feed.status, 200, feed.body.message);
    const feedIds = feed.body.events.map(event => event.id);
    assert.strictEqual(feedIds.length, 2, 'القائمة العامة تعرض المناسبتين المعتمدتين البالغتَي النشر وحدهما');
    assert.ok(!feedIds.includes(pending.body.eventId), 'المعلّقة غائبة عن القائمة العامة');
    assert.ok(!feedIds.includes(scheduledId), 'والمجدولة غائبة عن القائمة العامة');

    const mine = await statsRegionRow();
    assert.strictEqual(
      mine.upcoming_count, feedIds.length,
      'رقم الشريط هو عدد ما تعرضه القائمة العامة للمحافظة نفسها'
    );
  });

  await test('مناسبة «بالرابط فقط» معتمدة وقادمة لا تُعدّ في الشريط', async () => {
    const before = await statsRegionRow();
    assert.strictEqual(before.upcoming_count, 2, 'نقطة البداية معروفة قبل الاختبار');

    const hiddenId = await publishStatsEvent({ label: 'بالرابط', overrides: { visibility: 'link_only' } });
    const stored = await db.queryOne('SELECT status, visibility FROM events WHERE id = ?', [hiddenId]);
    assert.strictEqual(stored.status, 'approved', 'المناسبة معتمدة فعلاً — الاستثناء من الظهور وحده');
    assert.strictEqual(stored.visibility, 'link_only', 'وظهورها «بالرابط فقط»');

    const after = await statsRegionRow();
    assert.strictEqual(
      after.upcoming_count, before.upcoming_count,
      'العدّ لم يزد: لو سقط شرط visibility من القطعة المشتركة لصار ٣ هنا'
    );
  });

  await test('مناسبة انتهى امتدادها لا تُعدّ «قادمة» — وهي معتمدة ويجدها زائر في الأرشيف', async () => {
    const before = await statsRegionRow();

    const endedId = await publishStatsEvent({ label: 'المنتهية', day: STATS_ENDED_DAY });
    const archive = await api(
      'GET',
      `/api/events?archive=1&limit=100&search=${encodeURIComponent(statsStamp)}`,
      { region: statsRegionId }
    );
    assert.strictEqual(archive.status, 200, archive.body.message);
    assert.ok(
      archive.body.events.some(event => event.id === endedId),
      'الأرشيف يعرضها: الصفّ موجود ومعتمد، والفرق في حدّ «قادم» وحده'
    );

    const after = await statsRegionRow();
    assert.strictEqual(
      after.upcoming_count, before.upcoming_count,
      'العدّ لم يزد: لو سقط EVENT_SPAN_END_SQL_EVENTS >= CURDATE() لصارت المنتهية «قادمة» هنا'
    );
  });

  await test('الطلب الثاني خلال الكاش لا يستعلم شيئاً، وupdated_at لحظة التعبئة نفسها', async () => {
    assert.strictEqual(STATS_TICKER_CACHE_SECONDS, 300, 'مدة الكاش المطلوبة في التذكرة بالثواني');

    statsService.clearTickerCache();
    // عدّاد على `db.query` وحده (لا `queryOne`) — وهو المدخل الوحيد الذي يقرأ
    // به استعلام الشريط، فتسجيل الصفر هنا يعني «لم تصل القاعدة إطلاقاً». ولا
    // يُعدّ إلا استعلام الشريط نفسه (`AS upcoming_count`): أي قراءة أخرى من
    // مؤقّت خلفي أو طلب آخر لا تُفسد القياس.
    const originalQuery = db.query;
    let tickerQueries = 0;
    db.query = (sql, params) => {
      if (/AS upcoming_count/.test(sql)) tickerQueries += 1;
      return originalQuery.call(db, sql, params);
    };
    let first;
    let second;
    try {
      first = await api('GET', '/api/stats/ticker');
      tickerQueries = 0;
      // تأخير صغير بين الطلبين كي يكون تساوي `updated_at` دليلاً: كودٌ يختم
      // اللحظة عند كل ردّ (لا عند التعبئة) يُنتج سلسلة أخرى بعد ٢٠مللي، فيسقط
      // التأكيد. بلا التأخير قد يقع الطلبان في المللي ثانية نفسها فيمرّ الخطأ.
      await new Promise(resolve => setTimeout(resolve, 20));
      second = await api('GET', '/api/stats/ticker');
    } finally {
      db.query = originalQuery;
    }

    assert.strictEqual(first.status, 200, first.body.message);
    assert.strictEqual(second.status, 200, second.body.message);
    assert.strictEqual(tickerQueries, 0, 'الطلب داخل المدّة لم يستعلم: الكاش نطاقه العملية لا الطلب');
    assert.strictEqual(
      second.body.updated_at, first.body.updated_at,
      'updated_at يُختم لحظة التعبئة، فلا يتغيّر مع كل ردّ داخل المدّة'
    );
    assert.deepStrictEqual(second.body.regions, first.body.regions, 'ونفس الأعداد تُعاد كما حُسبت');
  });

  await test('الكاش هو ما يجمّد الرقم: مناسبة قادمة ثالثة لا تُحتسب حتى تنتهي مدّته، ثم تُحتسب', async () => {
    // ساعة الخدمة قابلة للاستبدال (`statsService.setTickerClock`): العبور هنا
    // بـ`STATS_TICKER_CACHE_SECONDS` نفسها التي يقيسها الكاش، لا بتفريغٍ يدوي.
    // لو صار الكاش أبدياً بقي هذا الاختبار أحمر: لا شيء في مساره يُفرغه.
    let fakeNow = Date.now();
    statsService.setTickerClock(() => fakeNow);

    // عدّاد على `db.query` وحده (الاختبار السابق يشرح لماذا): الصفر داخل
    // المدّة والواحد بعد عبورها هما الدليل على أن الطلب هو ما استعلم.
    const originalQuery = db.query;
    let tickerQueries = 0;
    db.query = (sql, params) => {
      if (/AS upcoming_count/.test(sql)) tickerQueries += 1;
      return originalQuery.call(db, sql, params);
    };

    try {
      // تفريغ واحد قبل القياس لبداية معروفة على صفوف هذا القسم — لا تفريغ
      // بعدها: مسار الانتهاء نفسه يمرّ بالساعة وحدها.
      statsService.clearTickerCache();
      const cached = await api('GET', '/api/stats/ticker');
      assert.strictEqual(cached.status, 200, cached.body.message);
      const cachedCount = cached.body.regions
        .find(region => region.region_id === statsRegionId).upcoming_count;

      await publishStatsEvent({ label: 'الثالثة' });

      tickerQueries = 0;
      const stillCached = await api('GET', '/api/stats/ticker');
      assert.strictEqual(stillCached.status, 200, stillCached.body.message);
      assert.strictEqual(tickerQueries, 0, 'داخل المدّة لا استعلام: النسخة المحفوظة هي ما يُخدَم');
      assert.strictEqual(
        stillCached.body.regions.find(region => region.region_id === statsRegionId).upcoming_count,
        cachedCount,
        'النسخة المحفوظة هي ما يُخدَم داخل المدّة — لا قراءة جديدة ترى المناسبة الثالثة'
      );
      assert.strictEqual(
        stillCached.body.updated_at, cached.body.updated_at,
        'وحتى انتهاء المدّة يحمل الردّ لحظة التعبئة نفسها، لا لحظة السؤال'
      );

      // نهاية المدّة بالضبط كما يقيسها الكاش: الساعة تتقدّم مدّة الصلاحية
      // كاملة + ثانية. لا مؤقّت في الخدمة ولا تفريغ — الطلب التالي بعد
      // الانتهاء هو ما يعيد التعبئة.
      fakeNow += STATS_TICKER_CACHE_SECONDS * 1000 + 1000;
      const refreshed = await api('GET', '/api/stats/ticker');
      assert.strictEqual(refreshed.status, 200, refreshed.body.message);
      assert.strictEqual(tickerQueries, 1, 'انتهاء المدّة وحده أعاد الاستعلام — لا شيء آخر جدّد');
      assert.strictEqual(
        refreshed.body.regions.find(region => region.region_id === statsRegionId).upcoming_count,
        cachedCount + 1,
        'وبعد انتهاء الصلاحية تُقرأ المناسبة الثالثة: الانتهاء هو ما جدّد'
      );
      assert.notStrictEqual(
        refreshed.body.updated_at, stillCached.body.updated_at,
        'ولحظة الحساب تتقدّم مع إعادة التعبئة — updated_at يُختم عند التعبئة ولا يُجمَّد أبدياً'
      );
    } finally {
      db.query = originalQuery;
      // الساعة الحقيقية تعود قبل التنظيف وما بعده من أقسام.
      statsService.setTickerClock();
    }
  });

  // تنظيف قسم الإحصائيات: المناسبات (ومعها إشعاراتها بـON DELETE CASCADE)، ثم
  // البلدة، ثم المحافظة — بترتيب المفاتيح الأجنبية. والكاش يُفرَّغ في آخره كي
  // لا يبقى فيه صفّ محافظة محذوفة.
  for (const id of statsCleanup.eventIds) {
    await api('DELETE', `/api/admin/events/${id}`, { token: superAdminToken });
  }
  for (const id of statsCleanup.townIds) await db.execute('DELETE FROM towns WHERE id = ?', [id]);
  for (const id of statsCleanup.regionIds) await db.execute('DELETE FROM regions WHERE id = ?', [id]);
  statsService.clearTickerCache();

  // =====================================================================
  // ستوديو بطاقة الدعوة (#180) — القوالب والمعاينة والحفظ في الخادم
  // =====================================================================
  console.log('\nستوديو بطاقة الدعوة — القوالب والمعاينة والحفظ (#180)');

  /**
   * حساب بصفّ مباشر في القاعدة ورمز موقَّع محلياً — نفس نمط `createDirectUser`
   * في قسم الإشعارات: ميزانية `authLimiter` (٢٠ في النافذة) مستهلكة قبل هنا.
   */
  async function createCardUser(fullName) {
    const phoneNumber = `05${Math.floor(10000000 + Math.random() * 89999999)}`;
    const { insertId } = await db.execute(
      `INSERT INTO users (phone_number, full_name, pin_code, clan_town, role) VALUES (?, ?, ?, ?, 'user')`,
      [phoneNumber, fullName, 'x', 'رهط']
    );
    return {
      id: insertId,
      phone: phoneNumber,
      token: signToken({ id: insertId, phone_number: phoneNumber, full_name: fullName, role: 'user' }, '1h')
    };
  }

  const { uploadsDir: uploadsDirForCards } = require('../src/middleware/upload');

  /**
   * أبعاد PNG من ترويسة IHDR نفسها (بايتات ١٦–٢٣)، لا من ترويسة Content-Type:
   * هذا ما يثبت أن المعاد بايتات PNG فعلية بالمقاس المعلن.
   */
  function pngDimensions(buffer) {
    assert.ok(Buffer.isBuffer(buffer) && buffer.length > 24, 'expected a real PNG buffer');
    assert.deepStrictEqual(
      [...buffer.slice(0, 8)],
      [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a],
      'expected the PNG signature'
    );
    assert.strictEqual(buffer.slice(12, 16).toString('latin1'), 'IHDR', 'expected the IHDR chunk first');
    return { width: buffer.readUInt32BE(16), height: buffer.readUInt32BE(20) };
  }

  /** POST متعدّد الأجزاء: يقرأ PNG لما يعود `image/png`، وJSON لغيرها. */
  async function postCardForm(urlPath, { token, fields = {}, file = null } = {}) {
    const form = new FormData();
    for (const [key, value] of Object.entries(fields)) form.append(key, value);
    // ملف حقيقي لحقل `photo` — نفس ما يرسله الويب في `photo_source: 'upload'`.
    if (file) form.append('photo', new Blob([file], { type: 'image/png' }), 'photo.png');
    const headers = { 'X-App-Version': '2.0.0' };
    if (token) headers.Authorization = `Bearer ${token}`;
    const res = await fetch(`${baseUrl}${urlPath}`, { method: 'POST', headers, body: form });
    const contentType = res.headers.get('content-type') || '';
    if (contentType.startsWith('image/png')) {
      return { status: res.status, contentType, buffer: Buffer.from(await res.arrayBuffer()) };
    }
    return { status: res.status, contentType, body: await res.json().catch(() => ({})) };
  }

  /** DELETE للبطاقة بنفس رمز المستخدم — `fetch` مباشر لأن الردّ JSON لا HTML. */
  async function deleteCardRequest(eventId, cardId, token) {
    const res = await fetch(`${baseUrl}/api/events/${eventId}/cards/${cardId}`, {
      method: 'DELETE',
      headers: { Authorization: `Bearer ${token}`, 'X-App-Version': '2.0.0' }
    });
    return { status: res.status, body: await res.json().catch(() => ({})) };
  }

  /**
   * أبعاد الصورة المحفوظة كما كتبها الخادم على القرص (`/uploads/…`)، أو null
   * حين خُزّنت على Cloudinary: ذاك حساب خارجي ولا يُنبش من الاختبار. مسار
   * الاختبار بلا مفاتيح Cloudinary عادةً، والرابط المطلق يُفحص في كل حال.
   */
  async function storedCardPng(imageUrl) {
    const text = String(imageUrl);
    if (!text.includes('/uploads/')) return null;
    const fileName = path.basename(text);
    assert.ok(fileName.endsWith('.png'), `expected a stored PNG, got ${imageUrl}`);
    return pngDimensions(await fsp.readFile(path.join(uploadsDirForCards, fileName)));
  }

  const cardOwner = await createCardUser('مالك بطاقة الدعوة');
  const cardStranger = await createCardUser('غريب بطاقة الدعوة');
  let cardEventId = 0;
  let cardFuneralEventId = 0;

  await test('Set up: مناسبة عرس ومناسبة عزاء معتمدتان لصاحب البطاقة', async () => {
    const wedding = await api('POST', '/api/events', {
      token: cardOwner.token,
      body: weddingEventBody({ honorees: [{ name: 'عريس بطاقة الاختبار' }], town: 'رهط', event_date: '2026-12-31' })
    });
    assert.strictEqual(wedding.status, 201, wedding.body.message);
    cardEventId = wedding.body.eventId;
    assert.strictEqual(wedding.body.status, 'pending', 'نشر المستخدم العادي يدخل الطابور أولاً');

    const approveWedding = await api('PATCH', `/api/admin/events/${cardEventId}/status`, {
      token: adminToken,
      body: { status: 'approved' }
    });
    assert.strictEqual(approveWedding.status, 200, approveWedding.body.message);

    const funeral = await api('POST', '/api/events', {
      token: cardOwner.token,
      body: {
        occasion_type_id: funeralType.id,
        honorees: [{ name: 'المرحوم بطاقة الاختبار' }],
        town: 'رهط',
        location_name: 'بيت العزاء',
        // «تاريخ الانتهاء» **إجباري في نوع عزا وحده** — قُرئ من القاعدة
        // (`occasion_type_fields`: is_visible = 1 و is_required = 1) لا من
        // التخمين: أنواع `festive` كلها تُخفيه، وعزا يفرضه. وغيابه هنا كان
        // يُسقط التهيئة بـ400 «تاريخ الانتهاء مطلوب»، فتسقط معها كل حالات
        // البطاقة التالية (ومعرّف مناسبة العزاء يبقى 0).
        event_date: '2026-12-30',
        event_end_date: '2026-12-31'
      }
    });
    assert.strictEqual(funeral.status, 201, funeral.body.message);
    cardFuneralEventId = funeral.body.eventId;
    // الحارس الذي كان يسقط صامتاً: معرّف الصفر يجعل كل طلبات البطاقة التالية
    // تذهب إلى `/api/events/0/…` فتردّ 400 «معرّف المناسبة غير صالح» بدل أن
    // تكشف سبب الفشل الحقيقي (غياب حقل إجباري في النشر).
    assert.ok(Number.isInteger(cardFuneralEventId) && cardFuneralEventId > 0, 'مناسبة العزاء لم تُنشأ — لا معرّف لها');
    const approveFuneral = await api('PATCH', `/api/admin/events/${cardFuneralEventId}/status`, {
      token: adminToken,
      body: { status: 'approved' }
    });
    assert.strictEqual(approveFuneral.status, 200, approveFuneral.body.message);
  });

